owing_url":"https://api.github.com/users/Sara-Qadi/following{/other_user}","gists_url":"https://api.github.com/users/Sara-Qadi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Sara-Qadi","id":180862618,"login":"Sara-Qadi","node_id":"U_kgDOCse-mg","organizations_url":"https://api.github.com/users/Sara-Qadi/orgs","received_events_url":"https://api.github.com/users/Sara-Qadi/received_events","repos_url":"https://api.github.com/users/Sara-Qadi/repos","site_admin":false,"starred_url":"https://api.github.com/users/Sara-Qadi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Sara-Qadi/subscriptions","type":"User","url":"https://api.github.com/users/Sara-Qadi","user_view_type":"public"},"comments_url":"https://api.github.com/repos/Sara-Qadi/fashion-elan-card-checkout/commits/a609a3f420209c20e8143a70c35a3f20442d2c18/comments","commit":{"author":{"date":"2026-08-02T20:58:45Z","email":"sara.2002.qado@gmail.com","name":"Sara-Qadi"},"comment_count":0,"committer":{"date":"2026-08-02T20:58:45Z","email":"sara.2002.qado@gmail.com","name":"Sara-Qadi"},"message":"Build ELAN Cart & Checkout microfrontend (Vue 3 + Vuetify 3 + Vite)\n\nImplements the full post-basket journey for the Team 1 fashion marketplace:\nshopping bag, shipping, mocked payment, review and order confirmation.\n\n- Pinia cart/checkout stores with one-directional dependency\n- All money rules centralised in utils/pricing.js\n- Route guards per checkout step, with readable redirect messages\n- Defensive localStorage layer that survives corrupted data\n- Mocked card payment: PAN and CVV never leave component state\n- Provisional CustomEvent integration boundary for the future shell\n- ELAN design tokens shared via src/theme/elanTheme.js\n- Vercel SPA rewrite so deep links survive a refresh\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"319ff7006bd5ccac0763b23f166878f359e679c9","url":"https://api.github.com/repos/Sara-Qadi/fashion-elan-card-checkout/git/trees/319ff7006bd5ccac0763b23f166878f359e679c9"},"url":"https://api.github.com/repos/Sara-Qadi/fashion-elan-card-checkout/git/commits/a609a3f420209c20e8143a70c35a3f20442d2c18","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/180862618?v=4","events_url":"https://api.github.com/users/Sara-Qadi/events{/privacy}","followers_url":"https://api.github.com/users/Sara-Qadi/followers","following_url":"https://api.github.com/users/Sara-Qadi/following{/other_user}","gists_url":"https://api.github.com/users/Sara-Qadi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Sara-Qadi","id":180862618,"login":"Sara-Qadi","node_id":"U_kgDOCse-mg","organizations_url":"https://api.github.com/users/Sara-Qadi/orgs","received_events_url":"https://api.github.com/users/Sara-Qadi/received_events","repos_url":"https://api.github.com/users/Sara-Qadi/repos","site_admin":false,"starred_url":"https://api.github.com/users/Sara-Qadi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Sara-Qadi/subscriptions","type":"User","url":"https://api.github.com/users/Sara-Qadi","user_view_type":"public"},"html_url":"https://github.com/Sara-Qadi/fashion-elan-card-checkout/commit/a609a3f420209c20e8143a70c35a3f20442d2c18","node_id":"C_kwDOTqyvCNoAKGE2MDlhM2Y0MjAyMDljMjBlODE0M2E3MGMzNWEzZjIwNDQyZDJjMTg","parents":[],"sha":"a609a3f420209c20e8143a70c35a3f20442d2c18","url":"https://api.github.com/repos/Sara-Qadi/fashion-elan-card-checkout/commits/a609a3f420209c20e8143a70c35a3f20442d2c18"}],"requestUrl":"https://api.github.com/repos/Sara-Qadi/fashion-elan-card-checkout/commits?per_page=100&page=1&sha=1c0df9084cfbd879fe35438e6c04ab42888c5595&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A43%3A50.409Z"}');
